 const el=(tag,attrs,parent=svg)=>{const n=document.createElementNS(ns,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,v);parent.append(n);return n;},poly=(p,attrs={},parent=svg)=>el('polygon',{points:p.map(p=>p.join(',')).join(' '),...attrs},parent),G=window.CityPlanGeometry;
 function showLot(id){selected=world.lots.find(l=>l.id===id);if(!selected)return;svg.querySelector('#selectedCore')?.remove();const g=el('g',{id:'selectedCore','pointer-events':'none'}),core=G.worldPoly(selected,selected.plan.usableCore);poly(core,{fill:'#ffe39e',stroke:'#b45b2a','stroke-width':.35},g);const s=selected.plan.stair,stairs=G.worldPoly(selected,G.rect(s.x,s.z,s.w,s.d));poly(stairs,{fill:'#4188bb',stroke:'#173c61','stroke-width':.25},g);for(let i=1;i<8;i++){const z=s.z+s.d*i/8,p=G.worldPoly(selected,[[s.x,z],[s.x+s.w,z]]);el('path',{d:`M${p[0]}L${p[1]}`,stroke:'#d5ecff','stroke-width':.08},g);}const c=selected.plan.usableCore[0],bed=G.worldPoly(selected,G.rect(c[0]+.3,c[1]+.3,1.5,2.0)),table=G.worldPoly(selected,G.rect(c[0]+2.5,c[1]+3.8,1.4,1.0));poly(bed,{fill:'#b5787c',stroke:'#61423b','stroke-width':.12},g);poly(table,{fill:'#a77e42',stroke:'#614923','stroke-width':.12},g);updatePanel();}
 function updatePanel(){panel.replaceChildren();const title=document.createElement('strong');title.textContent='City plan review';panel.append(title);const p=document.createElement('p');p.textContent=`${world.lots.length} homes · ${world.annexCount||0} attached wings · ${world.serviceBuildings?.length||0} workshops · ${world.workspaces?.length||0} outdoor bays`;panel.append(p);const quality=document.createElement('p');quality.textContent=`${world.audit.violations.length} road/building overlap or room-size violations`;panel.append(quality);const land=document.createElement('p');land.textContent=`${world.landUse.unusedPercent.toFixed(1)}% of buildable plot area remains unused. Roads, water and planned public spaces are separate.`;panel.append(land);const legend=document.createElement('p');legend.textContent='Dashed: plots · solid: buildings · gold: main routes · grey: local streets · aqua: water · green: bazaar/courts. Click a home to inspect its room core and stairs; drag and scroll to explore.';panel.append(legend);if(selected){const d=document.createElement('p');d.textContent=`${selected.id}: ${selected.plan.form}, ${selected.plan.storeys} floors. Ground floor ${G.area(selected.footprints[0]).toFixed(0)} m²; clear furnishing core 4.8 × 7.2 m plus separate stairs.`;panel.append(d);const inspect=document.createElement('button');inspect.textContent='View this frontage';inspect.onclick=()=>{view.hidden=true;button.textContent='Plan review';onInspect(selected);};panel.append(inspect);const bridge=world.bridges.find(b=>b.lots.includes(selected.id));if(bridge?.landings){const balcony=document.createElement('button');balcony.textContent='View balcony connection';balcony.onclick=()=>{view.hidden=true;button.textContent='Plan review';onInspect(selected,bridge.landings.find(l=>l.lot===selected.id));};panel.append(balcony);}}const exportButton=document.createElement('button');exportButton.textContent='Export plan SVG';exportButton.style.marginTop='8px';exportButton.onclick=()=>{const blob=new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='city-plan-'+world.seed+'.svg';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};panel.append(exportButton);}
 function render(w){world=w;selected=null;svg.replaceChildren();if(!world?.planned)return;const R=world.wallRadius;box=[-R-15,-R-15,2*R+30,2*R+30];svg.setAttribute('viewBox',box.join(' '));el('circle',{cx:0,cy:0,r:R,fill:'#d0c7ad',stroke:'#4f5d4c','stroke-width':1.5});const river=[[-R*1.3,R*.29-R*.13-world.riverWidth/2],[R*1.3,R*.29+R*.13-world.riverWidth/2],[R*1.3,R*.29+R*.13+world.riverWidth/2],[-R*1.3,R*.29-R*.13+world.riverWidth/2]];poly(river,{fill:'#7ab1b5'});poly(G.rect(world.canal.x-world.canal.width/2,R*.29+world.canal.x*.1,world.canal.width,R),{fill:'#7ab1b5'});for(const lane of world.lanes)poly(lane.poly,{fill:lane.tier==='primary'?'#c8a365':'#b5ad9a',stroke:'#9c9687','stroke-width':.15});for(const court of world.courtyards)poly(court.poly,{fill:court.central?'#9ab894':'#b8c0a4',stroke:'#768675','stroke-width':.25});for(const space of world.infill)poly(space.poly,{fill:'#d5b98e',stroke:'#be936b','stroke-width':.25});for(const site of world.landmarks)poly(site.footprint,{fill:site.mockup?'#788ba3':'#a4a6b1',stroke:'#384c61','stroke-width':.8});for(const stall of world.bazaarStalls||[])poly(stall.poly,{fill:'#785b78',stroke:'#493d49','stroke-width':.2});for(const building of world.serviceBuildings)poly(building.poly,{fill:'#8a7560',stroke:'#574d41','stroke-width':.3});const bad=new Set(world.audit.violations.map(v=>v.lot));for(const lot of world.lots){poly(lot.parcel,{fill:'none',stroke:'#998c62','stroke-width':.22,'stroke-dasharray':'1,.65','pointer-events':'none','data-plot':lot.id});const p=poly(lot.footprints[0],{fill:bad.has(lot.id)?'#d74c46':['#cb8a75','#9aadb5','#adb39b'][lot.palette],stroke:'#4c544a','stroke-width':.3,'data-lot':lot.id,tabindex:0});p.style.cursor='pointer';p.onclick=()=>showLot(lot.id);}for(const bay of world.workspaces||[]){const p=poly(bay.poly,{fill:'#c6a779',stroke:'#806542','stroke-width':.22,'data-workspace':bay.id});p.onclick=()=>showLot(bay.lot);}const center=el('text',{x:0,y:0,'font-size':4,'text-anchor':'middle',fill:'#244b36'});center.textContent='CENTRAL BAZAAR';for(const site of world.landmarks){const t=el('text',{x:site.x,y:site.z,'font-size':4,'text-anchor':'middle',fill:'#203447'});t.textContent=site.mockup?'CONCENTRIC CASTLE':site.id.toUpperCase();}updatePanel();}
 button.onclick=()=>{if(!getWorld()?.planned)return;view.hidden=!view.hidden;button.textContent=view.hidden?'Plan review':'Back to city';if(!view.hidden&&world!==getWorld())render(getWorld());};svg.onwheel=e=>{e.preventDefault();const factor=Math.exp(e.deltaY*.001),r=svg.getBoundingClientRect(),px=(e.clientX-r.left)/r.width,pz=(e.clientY-r.top)/r.height;box=[box[0]+box[2]*px*(1-factor),box[1]+box[3]*pz*(1-factor),box[2]*factor,box[3]*factor];svg.setAttribute('viewBox',box.join(' '));};svg.onpointerdown=e=>{const id=e.target.getAttribute('data-lot');if(id)showLot(id);drag=[e.clientX,e.clientY];svg.setPointerCapture(e.pointerId);};svg.onpointerup=()=>drag=null;svg.onpointermove=e=>{if(!drag)return;const r=svg.getBoundingClientRect();box[0]-=(e.clientX-drag[0])/r.width*box[2];box[1]-=(e.clientY-drag[1])/r.height*box[3];drag=[e.clientX,e.clientY];svg.setAttribute('viewBox',box.join(' '));};return {render,get selected(){return selected;},showLot};
